--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,60 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, seed } from "./helpers.js";
+import { migrate } from "../src/db/migrations.js";
+
+const ANNEX = { "x-larder-site": "annex" };
+const annexData = () => {
+  const data = seed();
+  data.batches.push({ id: 100, itemId: 1, lot: "A1", qty: 4, receivedOn: "2026-10-20", expires: null, location: "annex-fridge" });
+  data.seq.batch = 100;
+  return data;
+};
+const annexApp = async () => {
+  const { memoryStore } = await import("../src/db/store.js");
+  const { createApp } = await import("../src/http/server.js");
+  const store = memoryStore(annexData());
+  return createApp(store, { clock: () => Date.parse("2026-10-28T10:00:00Z") });
+};
+
+test("schema 2 files get the main site", () => {
+  const old = seed();
+  old.schemaVersion = 2;
+  delete old.sites;
+  old.locations.forEach((l) => delete l.site);
+  const data = migrate(old);
+  assert.deepEqual(data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const r = await handle({ path: "/items", headers: { "X-Larder-Site": "nope" } });
+  assert.equal(r.status, 400);
+  assert.equal(r.body.error.code, "unknown_site");
+});
+
+test("batches, stock and stock value only see the request's site", async () => {
+  const handle = await annexApp();
+  const main = await handle({ path: "/batches" });
+  const annex = await handle({ path: "/batches", headers: ANNEX });
+  assert.ok(main.body.length > 0 && main.body.every((b) => b.id !== 100));
+  assert.deepEqual(annex.body.map((b) => b.id), [100]);
+  assert.equal((await handle({ path: "/batches/100" })).status, 404);
+  const items = await handle({ path: "/items", headers: ANNEX });
+  assert.equal(items.body.find((i) => i.id === 1).onHand, 4);
+  const value = await handle({ path: "/reports/stock-value", headers: ANNEX });
+  assert.equal(value.body.totalCents, 4 * 180);
+});
+
+test("cooking and stock-takes stay inside the site", async () => {
+  const handle = await annexApp();
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(cook.body.error.code, "not_enough_stock");
+  const other = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "fridge" } });
+  assert.equal(other.body.error.code, "unknown_location");
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(take.status, 201);
+  const seen = await handle({ method: "POST", path: `/stocktakes/${take.body.id}/finish` });
+  assert.equal(seen.status, 404);
+});
